// ── 取得 userId 查詢參數 ─────────────────────────────────────────
const userId = String($('Vote Results Webhook').first().json.query?.userId ?? '').trim();

// ── 讀取選手名單 ─────────────────────────────────────────────────
const playerItems = $('Get Players from Notion').all();

function plainText(parts = []) {
  return (parts ?? []).map(p => p.plain_text ?? p.text?.content ?? '').join('').trim();
}

function readProp(prop) {
  if (!prop) return null;
  if (prop.type === 'title')   return plainText(prop.title);
  if (prop.type === 'rich_text') return plainText(prop.rich_text);
  if (prop.type === 'number')  return prop.number ?? null;
  if (prop.type === 'select')  return prop.select?.name ?? null;
  if (prop.type === 'url')     return prop.url ?? null;
  if (prop.type === 'files') {
    const f = prop.files?.[0];
    if (!f) return null;
    return f.type === 'file' ? (f.file?.url ?? null) : (f.external?.url ?? null);
  }
  return null;
}

// 建立 playerId → { name, photo } 對照表
const playersMap = {};
for (const item of playerItems) {
  const props = item.json.properties ?? item.json;
  const num   = readProp(props['選手編號']);
  const name  = readProp(props['選手名稱']) ?? readProp(props['名稱']) ?? '';
  const photo = readProp(props['選手照片']) ?? '';
  if (num != null) {
    playersMap[String(num)] = { name, photo };
  }
}

// ── 讀取投票資料 ─────────────────────────────────────────────────
const voteItems = $input.all();

const voteCounts = {};
let hasVoted = false;
let votedTarget = '';

for (const item of voteItems) {
  const props = item.json.properties ?? item.json;

  // 投票對象：select 欄位，值為選手編號字串 "1"/"2"...
  const candidateId = readProp(props['投票對象']);
  if (!candidateId) continue;

  voteCounts[candidateId] = (voteCounts[candidateId] || 0) + 1;

  // 判斷當前用戶是否已投票
  if (userId) {
    const lineUserId =
      readProp(props['LINE User ID']) ??
      readProp(item.json['LINE User ID']) ??
      item.json.name ?? '';
    if (String(lineUserId).trim() === userId) {
      hasVoted = true;
      votedTarget = playersMap[String(candidateId)]?.name ?? candidateId;
    }
  }
}

// ── 組合回傳格式（前端期待 { players, hasVoted, votedTarget }）────
const players = Object.keys(playersMap)
  .sort((a, b) => Number(a) - Number(b))
  .map(num => ({
    playerId:   num,
    playerName: playersMap[num].name,
    votes:      voteCounts[num] ?? 0,
    photoUrl:   playersMap[num].photo,
  }));

return [{
  json: { players, hasVoted, votedTarget },
}];
